using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;

namespace CombatSolver;

internal sealed partial class CombatBeamSolver
{
    // An exact optional-potion layer can affect the Smart selection only if it
    // meets the existing HP-saving threshold after a complete potion-free victory.
    // Component certification excludes new potion/relic acquisition and HP-growth
    // sources; branch-unknown sources retain the full counterfactual search.
    private readonly int? _smartPotionEligibilityHpCeiling =
        (directSearchPurpose == DirectSearchPurpose.SmartPotionGradient
            || CanUseComponentSmartPotionEligibility(root, policy)
                && attributionPurpose == ContinuationPurpose.SmartOpeningPotionPosterior)
        && policy.PotionPolicy == SolverPotionPolicy.Smart
        && !policy.PotionStrategy.HasForcedDirectives
        && policy.TheftPolicy != SolverTheftPolicy.PreserveResources
        && root.SearchablePotions.Count > 0
        && (CanUseComponentSmartPotionEligibility(root, policy)
            || (root.PlayerIdentity.Character.GetType() == typeof(MegaCrit.Sts2.Core.Models.Characters.Defect)
                && root.Enemies.Count > 0
                && root.Enemies.All(enemy => enemy.Monster?.GetType() == typeof(MegaCrit.Sts2.Core.Models.Monsters.InfestedPrism))
                && CanUseStrictHpRelicBound(root.CanCertifyRemainingHealing
                    && root.InitialRemainingHealingUpperBound == 0,
                    policy.EffectiveHasGrowthTargets, policy.RelicTargets)
                && root.SearchablePotions.Count > 0
                && root.SearchablePotions.All(potion => potion.PotionId
                    == MegaCrit.Sts2.Core.Models.ModelDb.Potion<MegaCrit.Sts2.Core.Models.Potions.FoulPotion>().Id.Entry)))
        && minimumPotionUses is > 0 && maximumPotionUses == minimumPotionUses
            ? SmartPotionEligibilityHpCeiling(potionFreePolicyBaseline,
                minimumPotionUses.Value, root.MinimumSearchablePotionStrategicCost!.Value,
                root.PotionRewardOutlook.ReplacementHpCredit,
                ActEndingBossPolicy.ResolveStrategicHpRelief(root.BossHpRelief,
                    policy.ActTransitionBossHpStrategy, policy.FinalBossHpStrategy))
            : null;

    internal static bool CanUseComponentSmartPotionEligibility(CombatRootSnapshot root, SearchPolicySnapshot policy)
        => root.UsesComponentHealingCertificate
            && root.SearchablePotions.Count > 0 && policy.PotionPolicy == SolverPotionPolicy.Smart
            && !policy.PotionStrategy.HasForcedDirectives
            && !policy.EffectiveHasGrowthTargets
            && (policy.RelicTargets.Count == 0 || CanUseStrictHpRelicBound(root, policy))
            && policy.TheftPolicy != SolverTheftPolicy.PreserveResources
            && (root.InitialRemainingHealingUpperBound == 0
                || StrategicHpRecoveryBound.ComponentHealingUpperBound(root.ForkSimulator(),
                    root.PlayerIdentity, postCombatHeal: 0,
                    potionStrategy: policy.PotionStrategy, effectivePotionPolicy: policy.PotionPolicy) == 0);

    private int _smartPotionEligibilityBranchesPruned;
    private int _closedStockEligibilityBranchesPruned;
    internal bool ComponentSmartBoundEnabledForTesting => _smartPotionEligibilityHpCeiling is not null;
    internal int ComponentSmartBoundPrunedForTesting => _smartPotionEligibilityBranchesPruned;

    internal static int? SmartPotionEligibilityHpCeiling(
        PotionFreePolicyBaseline? baseline, int exactPotionUses,
        int minimumPotionStrategicCost, int replacementHpCredit, BossHpRelief bossHpRelief)
    {
        if (baseline is not { Won: true, DeathSaveUseCount: 0 } audited
            || exactPotionUses <= 0 || minimumPotionStrategicCost < 0)
            return null;
        int minimumCost = checked(exactPotionUses * minimumPotionStrategicCost);
        return SmartPotionEligibilityHpCeilingForCost(baseline, exactPotionUses, minimumCost,
            replacementHpCredit, bossHpRelief);
    }

    internal static int? SmartPotionEligibilityHpCeilingForCost(
        PotionFreePolicyBaseline? baseline, int exactPotionUses, int minimumCost,
        int replacementHpCredit, BossHpRelief bossHpRelief)
    {
        if (baseline is not { Won: true, DeathSaveUseCount: 0 } audited
            || exactPotionUses <= 0 || minimumCost < 0)
            return null;
        int requiredHpSaved = PotionUsePolicy.SmartRequiredHpSaved(
            PotionUsePolicy.ApplyReplacementCredit(minimumCost, exactPotionUses, replacementHpCredit),
            bossHpRelief);
        return audited.HpDeficit - requiredHpSaved;
    }

    private List<SearchNode> ApplySmartPotionEligibilityBound(List<SearchNode> retained)
    {
        if (_smartPotionEligibilityHpCeiling is not { } ceiling)
            return retained;
        List<SearchNode>? bounded = null;
        for (int index = 0; index < retained.Count; index++)
        {
            SearchNode node = retained[index];
            int healing = RemainingHealingPotential(node.Snapshot);
            // Unknown branch sources retain the original exhaustive audit.
            if (root.UsesComponentHealingCertificate && healing == int.MaxValue)
            {
                bounded?.Add(node);
                continue;
            }
            int lowerBound = StrategicHpLowerBound(node.Snapshot, _strategicBossHpRelief, healing);
            bool oldBoundPrunes = lowerBound > ceiling;
            bool stockBoundPrunes = !oldBoundPrunes
                && root.ClosedPotionInventory is { } stock && node.Snapshot.HasSimulator
                && stock.MinimumExplicitCost((CombatPredictionSimulator)node.Snapshot.Simulator,
                    _player, _minimumPotionUses, healing) is { } cost
                && SmartPotionEligibilityHpCeilingForCost(_potionFreePolicyBaseline, _minimumPotionUses,
                    cost, root.PotionRewardOutlook.ReplacementHpCredit, _strategicBossHpRelief) is { } tighter
                && lowerBound > tighter;
            if (oldBoundPrunes || stockBoundPrunes)
            {
                if (bounded is null)
                {
                    bounded = new List<SearchNode>(retained.Count);
                    if (index > 0)
                        bounded.AddRange(retained.GetRange(0, index));
                }
                _smartPotionEligibilityBranchesPruned++;
                if (stockBoundPrunes)
                    _closedStockEligibilityBranchesPruned++;
                continue;
            }
            bounded?.Add(node);
        }
        return bounded ?? retained;
    }

    private void EmitSmartPotionEligibilityBoundDiagnostics()
    {
        policy.Diagnostics.Info("[CombatSolver/Test] TASK_EXACT_QUOTA_WITNESS " + TaskExactQuotaWitness.Snapshot());
        EmitRetainedPrimaryBoundDiagnostics();
        if (_smartPotionEligibilityHpCeiling is { } ceiling)
            policy.Diagnostics.Info($"[CombatSolver/Test] SMART_POTION_ELIGIBILITY_BOUND "
                + $"ceiling={ceiling} pruned={_smartPotionEligibilityBranchesPruned} "
                + $"closed_stock_extra={_closedStockEligibilityBranchesPruned}");
    }
}

using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;
using MegaCrit.Sts2.Core.Entities.Players;

namespace CombatSolver;

/// <summary>Frozen initial inventory within the separately audited no-acquisition closure.</summary>
internal sealed class ClosedInitialPotionInventory
{
    private readonly record struct Slot(int Index, string Id, int Cost);
    private readonly string?[] _initialIds;
    private readonly Slot[] _byCost;

    private ClosedInitialPotionInventory(string?[] ids, Slot[] byCost)
    {
        _initialIds = ids;
        _byCost = byCost;
    }

    internal static ClosedInitialPotionInventory? Capture(
        CombatPredictionSimulator simulator, Player player, bool renewableRock)
    {
        var combat = (SimulatedCombatState)simulator.State.CombatState;
        // Inventory-entry, alias and callback audit is pinned to this source
        // closure. Do not admit a gameplay subscriber merely certified non-healing.
        if (simulator.State.GetPlayerCombatState(player).Phase != MegaCrit.Sts2.Core.Combat.PlayerTurnPhase.Play
            || StrategicHpRecoveryBound.ComponentRootSourceRejection(simulator, player,
                requireClosedPotionInventory: true) is not null
            || combat.RootRunModSubscriberCount != 0 || combat.RootCombatModSubscriberCount != 0
            || StrategicHpRecoveryBound.ComponentHealingUpperBound(simulator, player, 0) == int.MaxValue)
            return null;
        int count = ((ICombatPredictionPlayerLimits)combat).GetPotionSlotCount(player);
        if (count > 64) return null;
        string?[] ids = new string?[count];
        List<Slot> costs = [];
        for (int index = 0; index < count; index++)
        {
            if (combat.GetPotionAtSlot(player, index) is not { } potion) continue;
            if (combat.IsFreeEntropicPotionAtSlot(player, index)) return null;
            ids[index] = potion.Id.Entry;
            costs.Add(new(index, potion.Id.Entry, PotionUsePolicy.StrategicHpCost(potion, renewableRock)));
        }
        return new(ids, costs.OrderBy(slot => slot.Cost).ThenBy(slot => slot.Index).ToArray());
    }

    // A finite component allowance witnesses the branch's reviewed source types;
    // its numerical HP value is irrelevant to the independent inventory proof.
    // Every slot is considered, even if protected, unsearchable or unusable now:
    // including a cheaper impossible use can only loosen this lower bound.
    internal int? MinimumExplicitCost(CombatPredictionSimulator simulator, Player player,
        int requiredUses, int componentHealingAllowance)
    {
        if (componentHealingAllowance == int.MaxValue || requiredUses <= 0 || simulator.HasPendingChoice)
            return null;
        var combat = (SimulatedCombatState)simulator.State.CombatState;
        if (((ICombatPredictionPlayerLimits)combat).GetPotionSlotCount(player) != _initialIds.Length)
            return null;
        ulong consumed = 0;
        int explicitUses = 0;
        int spent = 0;
        foreach (PredictedPotionUse use in combat.PotionUses)
        {
            if ((uint)use.Slot >= (uint)_initialIds.Length
                || _initialIds[use.Slot] != use.PotionId || (consumed & (1UL << use.Slot)) != 0
                || use.StrategicHpCost < 0)
                return null;
            consumed |= 1UL << use.Slot;
            if (use.Automatic) continue;
            explicitUses++;
            spent = checked(spent + use.StrategicHpCost);
        }
        for (int slot = 0; slot < _initialIds.Length; slot++)
        {
            var potion = combat.GetPotionAtSlot(player, slot);
            if (potion is not null && (potion.Id.Entry != _initialIds[slot]
                || (consumed & (1UL << slot)) != 0 || combat.IsFreeEntropicPotionAtSlot(player, slot)))
                return null;
        }
        int needed = Math.Max(0, requiredUses - explicitUses);
        foreach (Slot slot in _byCost)
        {
            if (needed == 0) break;
            if (combat.GetPotionAtSlot(player, slot.Index) is null) continue;
            spent = checked(spent + slot.Cost);
            needed--;
        }
        // This prototype does not turn insufficient stock into a no-route prune.
        return needed == 0 ? spent : null;
    }
}

