using System.Diagnostics;
using System.Text.Json;
namespace CombatSolver;
internal static class TaskRetainedPrimaryCost
{
    private static long Calls, Ticks;
    internal static void Record(long ticks)
    { Interlocked.Increment(ref Calls); Interlocked.Add(ref Ticks, ticks); }
    internal static string Snapshot() => JsonSerializer.Serialize(new
    { calls = Calls, totalQueryMilliseconds = Ticks * 1000.0 / Stopwatch.Frequency });
}

